-- DOCUMENTATION ONLY. PostgreSQL 16. Never execute from this project.
-- ids are generated by the application (no DB defaults).

-- Global catalog (not clinic-owned). key format: action:resource:scope
CREATE TABLE permissions (
  id       uuid PRIMARY KEY,
  key      text NOT NULL UNIQUE CHECK (key ~ '^(view|create|update|deactivate):(branches|users|roles|patients|audit_log|clinic_settings):(clinic|branch)$'),
  action   text NOT NULL,
  resource text NOT NULL,
  scope    text NOT NULL,
  module   text NULL CHECK (module IN ('patients'))
);
